/* From Uiverse.io by DellBee - Tags: input */
/* use it in dark theme */
.__UIV_SCOPE__ .input-container {
  position: relative;
  margin: 50px auto;
  width: 190px;
}

.__UIV_SCOPE__ .input-container input[type="text"] {
  font-size: 20px;
  color: rgb(255, 255, 255);
  border: none;
  border-bottom: 2px solid #a5a2a2;
  outline: none;
  width: 100%;
  background-color: transparent;
}

.__UIV_SCOPE__ .label {
  transition: all 0.3s ease;
  color: #d3d2d2;
  position: absolute;
  top: 0;
  left: 0;
  pointer-events: none;
}

.__UIV_SCOPE__ .input-container input[type="text"]:focus~.label,
        .__UIV_SCOPE__ .input-container input[type="text"]:valid~.label {
  top: -20px;
  transition: 0.3s;
  color: rgb(172, 46, 172);
}

.__UIV_SCOPE__ .input-container .underline {
  position: absolute;
  bottom: 4px;
  left: -7px;
  height: 2px;
  width: 110%;
  background-color: rgb(172, 46, 172);
  transform: scaleX(0);
}

.__UIV_SCOPE__ .input-container .sideline {
  position: relative;
  bottom: 15px;
  right: 18px;
  height: 2px;
  width: 18%;
  background-color: rgb(172, 46, 172);
  transform: scaleX(0);
  rotate: 90deg;
}

.__UIV_SCOPE__ .input-container .upperline {
  position: absolute;
  bottom: 30px;
  left: -8px;
  height: 2px;
  width: 110%;
  background-color: rgb(172, 46, 172);
  transform: scaleX(0);
}

.__UIV_SCOPE__ .input-container .line {
  position: relative;
  bottom: 17px;
  left: 178px;
  height: 2px;
  width: 18%;
  background-color: rgb(172, 46, 172);
  transform: scaleX(0);
  rotate: 90deg;
}

.__UIV_SCOPE__ .input-container input[type="text"]:focus~.underline,
        .__UIV_SCOPE__ .input-container input[type="text"]:valid~.underline {
  transform: scaleX(1);
  transition: 1s;
}

.__UIV_SCOPE__ .input-container input[type="text"]:focus~.sideline,
        .__UIV_SCOPE__ .input-container input[type="text"]:valid~.sideline {
  transform: scaleX(1);
  transition: 1s;
}

.__UIV_SCOPE__ .input-container input[type="text"]:focus~.upperline,
        .__UIV_SCOPE__ .input-container input[type="text"]:valid~.upperline {
  transform: scaleX(1);
  transition: 1s;
}

.__UIV_SCOPE__ .input-container input[type="text"]:focus~.line,
        .__UIV_SCOPE__ .input-container input[type="text"]:valid~.line {
  transform: scaleX(1);
  transition: 1s;
}
